<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ProductVariant extends Model{protected $fillable=['product_id','name','sku','attributes','price','discount_price','stock','status'];protected $casts=['attributes'=>'array','price'=>'decimal:2','discount_price'=>'decimal:2','status'=>'boolean'];public function product(){return $this->belongsTo(Product::class);}public function getSalePriceAttribute(){return (float)($this->discount_price??$this->price??$this->product->sale_price);}}
